#include "outputs.h"
#include "main.h"
#include "vehicle.h"
#include "blinker.h"
Outputs_t outputs={0};
void Outputs_Update(void){VehicleState_t *state=Vehicle_GetState(); bool blink=Blinker_GetPhase(); switch(state->blinkMode){case BLINK_LEFT:outputs.leftBlinker=blink;outputs.rightBlinker=false;break;case BLINK_RIGHT:outputs.leftBlinker=false;outputs.rightBlinker=blink;break;case BLINK_HAZARD:outputs.leftBlinker=blink;outputs.rightBlinker=blink;break;default:outputs.leftBlinker=false;outputs.rightBlinker=false;break;} outputs.lowBeam=(state->light!=LIGHT_OFF); outputs.highBeam=(state->light==LIGHT_HIGH); outputs.horn=state->horn; HAL_GPIO_WritePin(Blinklinks_out_GPIO_Port,Blinklinks_out_Pin,outputs.leftBlinker?GPIO_PIN_SET:GPIO_PIN_RESET); HAL_GPIO_WritePin(Blinkrechts_out_GPIO_Port,Blinkrechts_out_Pin,outputs.rightBlinker?GPIO_PIN_SET:GPIO_PIN_RESET); HAL_GPIO_WritePin(Abblendlicht_out_GPIO_Port,Abblendlicht_out_Pin,outputs.lowBeam?GPIO_PIN_SET:GPIO_PIN_RESET); HAL_GPIO_WritePin(Fernlicht_out_GPIO_Port,Fernlicht_out_Pin,outputs.highBeam?GPIO_PIN_SET:GPIO_PIN_RESET); HAL_GPIO_WritePin(Hupe_out_GPIO_Port,Hupe_out_Pin,outputs.horn?GPIO_PIN_SET:GPIO_PIN_RESET); HAL_GPIO_WritePin(Reserve_out_GPIO_Port,Reserve_out_Pin,GPIO_PIN_RESET);}
